<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="card p-4"><h2>Check out book</h2><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><div class="col-12"><label class="form-label">Book</label><select name="book_id" class="form-select" required><option value="">Select an available book</option><?php foreach($books as $b):?><option value="<?= $b['id'] ?>"><?= Security::e($b['title']) ?> (<?= $b['available_quantity'] ?> available)</option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Borrower name</label><input name="borrower_name" class="form-control" required></div><div class="col-md-6"><label class="form-label">Borrower ID</label><input name="borrower_id" class="form-control" required></div><div class="col-md-4"><label class="form-label">Due date</label><input name="due_date" type="date" value="<?= date('Y-m-d',strtotime('+14 days')) ?>" class="form-control" required></div><div class="col-12"><button class="btn btn-pink">Check out</button></div></form></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
